/** Exists only to hold a block or a card number; every active student and staff member can borrow without a row. */
export const libraryMembers = defineTable(
  'library_members',
  { module: 'M31', scope: 'branch', family: 'studentId' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    memberKind: enumText(libraryMemberMemberKinds).notNull(),
    /** required for a student */
    studentId: uuid().references((): AnyPgColumn => students.id),
    /** required for staff */
    staffId: uuid().references((): AnyPgColumn => staff.id),
    cardNo: text(),
    isBlocked: boolean().notNull().default(false),
    /** required when blocked */
    blockedReason: text(),
  },
  (t) => [
    check(
      'library_members_student_id_needed',
      sql`${t.memberKind} <> 'student' or ${t.studentId} is not null`,
    ),
    check(
      'library_members_staff_id_needed',
      sql`${t.memberKind} <> 'staff' or ${t.staffId} is not null`,
    ),
    check(
      'library_members_blocked_reason_needed',
      sql`not ${t.isBlocked} or ${t.blockedReason} is not null`,
    ),
    uniqueIndex('library_members_branch_student_uq')
      .on(t.branchId, t.studentId)
      .where(sql`${t.deletedAt} is null and ${t.studentId} is not null`),
    uniqueIndex('library_members_branch_staff_uq')
      .on(t.branchId, t.staffId)
      .where(sql`${t.deletedAt} is null and ${t.staffId} is not null`),
  ],
);

